    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) tooLarge = true;
      else chunks.push(chunk);
    });
    req.on('end', () => resolve({ text: Buffer.concat(chunks).toString('utf8'), tooLarge }));
    req.on('error', reject);
  });
}

async function createJob(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { text, tooLarge } = await readBody(req);
  const errors: FieldError[] = [];

  const keyHeader = req.headers['idempotency-key'];
  let key: string | null = null;
  if (keyHeader !== undefined) {
    if (typeof keyHeader === 'string' && KEY_PATTERN.test(keyHeader)) key = keyHeader;
    else errors.push({ field: 'Idempotency-Key', message: 'must match ^[A-Za-z0-9_-]{1,128}$' });
  }

  const parsed = parseSubmission(req.headers['content-type'], text, tooLarge);
  errors.push(...parsed.errors);
  if (errors.length > 0 || !parsed.payload) return invalid(res, errors);
  const payload = parsed.payload;

  const outcome = transaction(db, (): { status: number; row?: JobRow } => {
    if (key !== null) {
      const existing = getJobByKey(db, key);
      if (existing) {
        const same = existing.input === payload.input && existing.steps === payload.steps && existing.fail_attempts === payload.failAttempts;
        return same ? { status: 200, row: existing } : { status: 409 };
      }
    }
    const row = insertJob(db, { id: randomUUID(), ...payload, idempotencyKey: key });
    return { status: 201, row };
  });

  if (outcome.status === 409) {
    return sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
  }
  sendJson(res, outcome.status, toJob(outcome.row!));
}

function notAllowed(res: ServerResponse, allow: string): void {
  sendJson(res, 405, { error: { code: 'method_not_allowed', message: 'Method not allowed.' } }, { allow });
}

async function route(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const path = new URL(req.url ?? '/', 'http://localhost').pathname;
  const method = req.method ?? '';

  if (path === '/health') {
    if (method !== 'GET') return notAllowed(res, 'GET');
    return sendJson(res, 200, { status: 'ok', worker: workerAlive(db, Date.now()) ? 'up' : 'down' });
  }
  if (path === '/') {
    if (method !== 'GET') return notAllowed(res, 'GET');
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }
  if (path === '/api/jobs') {
    if (method === 'GET') return sendJson(res, 200, { jobs: listJobs(db).map(toJob) });
    if (method === 'POST') return createJob(req, res);
    return notAllowed(res, 'GET, POST');
  }
  const match = JOB_PATH.exec(path);
  if (match) {
    if (method !== 'GET') return notAllowed(res, 'GET');
    let id: string | undefined;
    try {
      id = decodeURIComponent(match[1]!);
    } catch {
      id = undefined;
    }
    const row = id === undefined ? undefined : getJobById(db, id);
    if (!row) return sendError(res, 404, 'not_found', 'Job not found.');
    return sendJson(res, 200, toJob(row));
  }
  sendError(res, 404, 'not_found', 'Not found.');
}

const port = Number(process.env.PORT || 3000);
const server = createServer((req, res) => {
  route(req, res).catch((e: unknown) => {
    console.error(e);
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal error.');
    else res.end();
  });
});

let closing = false;
function shutdown(): void {
  if (closing) return;
  closing = true;
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeAllConnections();
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

server.listen(port, () => console.log(`server listening on ${port}`));
